import csv
import math
from collections import defaultdict, Counter
from datetime import datetime

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            'name': row['Name'].strip(),
            'author': row['Author'].strip(),
            'rating': float(row['User Rating']),
            'reviews': int(row['Reviews']),
            'price': int(row['Price']),
            'year': int(row['Year']),
            'genre': row['Genre'].strip(),
        })

N = len(rows)

# ── Helper functions ───────────────────────────────────────────────────────
def mean(vals):
    return sum(vals) / len(vals) if vals else 0

def median(vals):
    s = sorted(vals)
    n = len(s)
    if n == 0: return 0
    if n % 2 == 1: return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2

def stdev(vals):
    m = mean(vals)
    return math.sqrt(sum((x - m) ** 2 for x in vals) / len(vals)) if len(vals) > 1 else 0

def pearson(xs, ys):
    n = len(xs)
    if n == 0: return 0
    mx, my = mean(xs), mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    den = math.sqrt(sum((x - mx) ** 2 for x in xs) * sum((y - my) ** 2 for y in ys))
    return num / den if den != 0 else 0

def pct(val, total):
    return f"{val / total * 100:.1f}%" if total else "0%"

def fmt(val, decimals=2):
    return f"{val:.{decimals}f}"

# ── Section 1: Market Overview ─────────────────────────────────────────────
all_ratings = [r['rating'] for r in rows]
all_prices = [r['price'] for r in rows]
all_reviews = [r['reviews'] for r in rows]

fiction_rows = [r for r in rows if r['genre'] == 'Fiction']
nonfiction_rows = [r for r in rows if r['genre'] == 'Non Fiction']
n_fiction = len(fiction_rows)
n_nonfiction = len(nonfiction_rows)

avg_rating = mean(all_ratings)
avg_price = mean(all_prices)
avg_reviews = mean(all_reviews)
med_price = median(all_prices)
min_price = min(all_prices)
max_price = max(all_prices)
min_rating = min(all_ratings)
max_rating = max(all_ratings)

unique_books = len(set(r['name'] for r in rows))
unique_authors = len(set(r['author'] for r in rows))
total_reviews = sum(all_reviews)

# ── Section 2: Price-Rating Correlation ─────────────────────────────────────
price_rating_r = pearson(all_prices, all_ratings)

# By genre
fiction_r = pearson([r['price'] for r in fiction_rows], [r['rating'] for r in fiction_rows])
nonfiction_r = pearson([r['price'] for r in nonfiction_rows], [r['rating'] for r in nonfiction_rows])

# ── Section 3: Genre Comparison ────────────────────────────────────────────
fiction_avg_price = mean([r['price'] for r in fiction_rows])
fiction_avg_rating = mean([r['rating'] for r in fiction_rows])
fiction_avg_reviews = mean([r['reviews'] for r in fiction_rows])
fiction_med_price = median([r['price'] for r in fiction_rows])

nf_avg_price = mean([r['price'] for r in nonfiction_rows])
nf_avg_rating = mean([r['rating'] for r in nonfiction_rows])
nf_avg_reviews = mean([r['reviews'] for r in nonfiction_rows])
nf_med_price = median([r['price'] for r in nonfiction_rows])

# ── Section 4: Year-over-Year Trends ──────────────────────────────────────
year_stats = {}
for year in range(2009, 2020):
    yr_rows = [r for r in rows if r['year'] == year]
    yr_fiction = [r for r in yr_rows if r['genre'] == 'Fiction']
    yr_nf = [r for r in yr_rows if r['genre'] == 'Non Fiction']
    year_stats[year] = {
        'avg_price': mean([r['price'] for r in yr_rows]),
        'avg_rating': mean([r['rating'] for r in yr_rows]),
        'avg_reviews': mean([r['reviews'] for r in yr_rows]),
        'total_reviews': sum(r['reviews'] for r in yr_rows),
        'count': len(yr_rows),
        'fiction_count': len(yr_fiction),
        'nf_count': len(yr_nf),
        'fiction_avg_price': mean([r['price'] for r in yr_fiction]) if yr_fiction else 0,
        'nf_avg_price': mean([r['price'] for r in yr_nf]) if yr_nf else 0,
        'fiction_avg_rating': mean([r['rating'] for r in yr_fiction]) if yr_fiction else 0,
        'nf_avg_rating': mean([r['rating'] for r in yr_nf]) if yr_nf else 0,
    }

# ── Section 5: Top Authors ────────────────────────────────────────────────
author_counter = Counter(r['author'] for r in rows)
top_authors_data = []
for author, count in author_counter.most_common(10):
    author_rows = [r for r in rows if r['author'] == author]
    top_authors_data.append({
        'author': author,
        'appearances': count,
        'avg_rating': mean([r['rating'] for r in author_rows]),
        'avg_price': mean([r['price'] for r in author_rows]),
        'total_reviews': sum(r['reviews'] for r in author_rows),
        'genres': list(set(r['genre'] for r in author_rows)),
        'book_count': len(set(r['name'] for r in author_rows)),
    })

# ── Price segments ─────────────────────────────────────────────────────────
price_segments = {
    'Budget ($0-$5)': [r for r in rows if 0 <= r['price'] <= 5],
    'Mid-Low ($6-$10)': [r for r in rows if 6 <= r['price'] <= 10],
    'Mid ($11-$15)': [r for r in rows if 11 <= r['price'] <= 15],
    'Mid-High ($16-$25)': [r for r in rows if 16 <= r['price'] <= 25],
    'Premium ($26+)': [r for r in rows if r['price'] >= 26],
}
segment_stats = {}
for seg, seg_rows in price_segments.items():
    segment_stats[seg] = {
        'count': len(seg_rows),
        'avg_rating': mean([r['rating'] for r in seg_rows]) if seg_rows else 0,
        'avg_reviews': mean([r['reviews'] for r in seg_rows]) if seg_rows else 0,
    }

# ── Inflection points ─────────────────────────────────────────────────────
price_changes = []
rating_changes = []
years_list = list(range(2009, 2020))
for i in range(1, len(years_list)):
    prev = year_stats[years_list[i-1]]
    curr = year_stats[years_list[i]]
    price_chg = curr['avg_price'] - prev['avg_price']
    rating_chg = curr['avg_rating'] - prev['avg_rating']
    price_changes.append((years_list[i], price_chg))
    rating_changes.append((years_list[i], rating_chg))

# ── Generate HTML ──────────────────────────────────────────────────────────

# Year-over-year chart data
years_js = str(years_list)
avg_prices_js = str([round(year_stats[y]['avg_price'], 2) for y in years_list])
avg_ratings_js = str([round(year_stats[y]['avg_rating'], 2) for y in years_list])
avg_reviews_js = str([round(year_stats[y]['avg_reviews'], 0) for y in years_list])
fiction_avg_prices_js = str([round(year_stats[y]['fiction_avg_price'], 2) for y in years_list])
nf_avg_prices_js = str([round(year_stats[y]['nf_avg_price'], 2) for y in years_list])
fiction_avg_ratings_js = str([round(year_stats[y]['fiction_avg_rating'], 2) for y in years_list])
nf_avg_ratings_js = str([round(year_stats[y]['nf_avg_rating'], 2) for y in years_list])

# Scatter data
scatter_data = [[r['price'], r['rating']] for r in rows]
scatter_fiction = [[r['price'], r['rating']] for r in fiction_rows]
scatter_nf = [[r['price'], r['rating']] for r in nonfiction_rows]

# Price segment chart data
seg_labels = list(segment_stats.keys())
seg_counts = [segment_stats[s]['count'] for s in seg_labels]
seg_ratings = [round(segment_stats[s]['avg_rating'], 2) for s in seg_labels]

