import csv
import math
from collections import defaultdict, Counter
from datetime import datetime

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            'name': row['Name'].strip(),
            'author': row['Author'].strip(),
            'rating': float(row['User Rating']),
            'reviews': int(row['Reviews']),
            'price': int(row['Price']),
            'year': int(row['Year']),
            'genre': row['Genre'].strip(),
        })

N = len(rows)

# ── Helper functions ───────────────────────────────────────────────────────
def mean(vals):
    return sum(vals) / len(vals) if vals else 0

def median(vals):
    s = sorted(vals)
    n = len(s)
    if n == 0: return 0
    if n % 2 == 1: return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2

def stdev(vals):
    m = mean(vals)
    return math.sqrt(sum((x - m) ** 2 for x in vals) / len(vals)) if len(vals) > 1 else 0

def pearson(xs, ys):
    n = len(xs)
    if n == 0: return 0
    mx, my = mean(xs), mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    den = math.sqrt(sum((x - mx) ** 2 for x in xs) * sum((y - my) ** 2 for y in ys))
    return num / den if den != 0 else 0

def pct(val, total):
    return f"{val / total * 100:.1f}%" if total else "0%"

def fmt(val, decimals=2):
    return f"{val:.{decimals}f}"

# ── Section 1: Market Overview ─────────────────────────────────────────────
all_ratings = [r['rating'] for r in rows]
all_prices = [r['price'] for r in rows]
all_reviews = [r['reviews'] for r in rows]

fiction_rows = [r for r in rows if r['genre'] == 'Fiction']
nonfiction_rows = [r for r in rows if r['genre'] == 'Non Fiction']
n_fiction = len(fiction_rows)
n_nonfiction = len(nonfiction_rows)

avg_rating = mean(all_ratings)
avg_price = mean(all_prices)
avg_reviews = mean(all_reviews)
med_price = median(all_prices)
min_price = min(all_prices)
max_price = max(all_prices)
min_rating = min(all_ratings)
max_rating = max(all_ratings)

unique_books = len(set(r['name'] for r in rows))
unique_authors = len(set(r['author'] for r in rows))
total_reviews = sum(all_reviews)

# ── Section 2: Price-Rating Correlation ─────────────────────────────────────
price_rating_r = pearson(all_prices, all_ratings)

# By genre
fiction_r = pearson([r['price'] for r in fiction_rows], [r['rating'] for r in fiction_rows])
nonfiction_r = pearson([r['price'] for r in nonfiction_rows], [r['rating'] for r in nonfiction_rows])

# ── Section 3: Genre Comparison ────────────────────────────────────────────
fiction_avg_price = mean([r['price'] for r in fiction_rows])
fiction_avg_rating = mean([r['rating'] for r in fiction_rows])
fiction_avg_reviews = mean([r['reviews'] for r in fiction_rows])
fiction_med_price = median([r['price'] for r in fiction_rows])

nf_avg_price = mean([r['price'] for r in nonfiction_rows])
nf_avg_rating = mean([r['rating'] for r in nonfiction_rows])
