nf_med_price = median([r['price'] for r in nonfiction_rows])

# ── Section 4: Year-over-Year Trends ──────────────────────────────────────
year_stats = {}
for year in range(2009, 2020):
    yr_rows = [r for r in rows if r['year'] == year]
    yr_fiction = [r for r in yr_rows if r['genre'] == 'Fiction']
    yr_nf = [r for r in yr_rows if r['genre'] == 'Non Fiction']
    year_stats[year] = {
        'avg_price': mean([r['price'] for r in yr_rows]),
        'avg_rating': mean([r['rating'] for r in yr_rows]),
        'avg_reviews': mean([r['reviews'] for r in yr_rows]),
        'total_reviews': sum(r['reviews'] for r in yr_rows),
        'count': len(yr_rows),
        'fiction_count': len(yr_fiction),
        'nf_count': len(yr_nf),
        'fiction_avg_price': mean([r['price'] for r in yr_fiction]) if yr_fiction else 0,
        'nf_avg_price': mean([r['price'] for r in yr_nf]) if yr_nf else 0,
        'fiction_avg_rating': mean([r['rating'] for r in yr_fiction]) if yr_fiction else 0,
        'nf_avg_rating': mean([r['rating'] for r in yr_nf]) if yr_nf else 0,
    }

# ── Section 5: Top Authors ────────────────────────────────────────────────
author_counter = Counter(r['author'] for r in rows)
top_authors_data = []
for author, count in author_counter.most_common(10):
    author_rows = [r for r in rows if r['author'] == author]
    top_authors_data.append({
        'author': author,
        'appearances': count,
        'avg_rating': mean([r['rating'] for r in author_rows]),
        'avg_price': mean([r['price'] for r in author_rows]),
        'total_reviews': sum(r['reviews'] for r in author_rows),
        'genres': list(set(r['genre'] for r in author_rows)),
        'book_count': len(set(r['name'] for r in author_rows)),
    })

# ── Price segments ─────────────────────────────────────────────────────────
price_segments = {
    'Budget ($0-$5)': [r for r in rows if 0 <= r['price'] <= 5],
    'Mid-Low ($6-$10)': [r for r in rows if 6 <= r['price'] <= 10],
    'Mid ($11-$15)': [r for r in rows if 11 <= r['price'] <= 15],
    'Mid-High ($16-$25)': [r for r in rows if 16 <= r['price'] <= 25],
    'Premium ($26+)': [r for r in rows if r['price'] >= 26],
}
segment_stats = {}
for seg, seg_rows in price_segments.items():
    segment_stats[seg] = {
        'count': len(seg_rows),
        'avg_rating': mean([r['rating'] for r in seg_rows]) if seg_rows else 0,
        'avg_reviews': mean([r['reviews'] for r in seg_rows]) if seg_rows else 0,
    }

# ── Inflection points ─────────────────────────────────────────────────────
price_changes = []
rating_changes = []
years_list = list(range(2009, 2020))
for i in range(1, len(years_list)):
    prev = year_stats[years_list[i-1]]
    curr = year_stats[years_list[i]]
    price_chg = curr['avg_price'] - prev['avg_price']
    rating_chg = curr['avg_rating'] - prev['avg_rating']
    price_changes.append((years_list[i], price_chg))
    rating_changes.append((years_list[i], rating_chg))

